async function rpc(rpcUrl: string, method: string, params: unknown[]): Promise<unknown> {
  const response = await fetch(rpcUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
  });
  const body = (await response.json()) as { result?: unknown; error?: unknown };
  if (body.error !== undefined) throw new Error(`${method} failed: ${JSON.stringify(body.error)}`);
  return body.result;
}

async function setCode(rpcUrl: string, address: string, code: string, hash: string) {
  if (keccak256(code as `0x${string}`) !== hash) {
    throw new Error(`vendored bytecode for ${address} does not match its pinned hash`);
  }
  await rpc(rpcUrl, 'anvil_setCode', [address, code]);
}

/** Puts Permit2 and the x402 proxy at their canonical addresses on an Anvil node */
export async function installPermit2(rpcUrl: string): Promise<void> {
  await setCode(rpcUrl, PERMIT2_ADDRESS, PERMIT2_CODE, PERMIT2_CODE_HASH);
  await setCode(rpcUrl, x402ExactPermit2ProxyAddress, PERMIT2_PROXY_CODE, PERMIT2_PROXY_CODE_HASH);
}

/** Puts Multicall3 at its canonical address on an Anvil node */
export async function installMulticall3(rpcUrl: string): Promise<void> {
  await setCode(rpcUrl, MULTICALL3_ADDRESS, MULTICALL3_CODE, MULTICALL3_CODE_HASH);
}
